mod audio;mod game;mod video;use game::Game;
fn main(){let mut out=vec![];for terrain in [0,1] {for input in [0,1,2,4,8,5,6,9,10] {let mut g=Game::new(false).unwrap();g.memory.fill(0);g.memory[0x300..0x500].fill(terrain*0x55);g.memory[0x30]=5;g.memory[0x530]=1;g.memory[0x56]=128;g.memory[0x58]=128;g.memory[0x62]=1;g.memory[0x64]=1;g.memory[0x68]=1;g.memory[0xf1]=input;let mut samples=vec![];for tick in 0..12 {g.memory[0x1a]=tick as u8;g.actor_call(0xea02,0).unwrap();samples.push(serde_json::json!({"tick":tick,"x":g.memory[0x56]as f32+g.memory[0x5d0]as f32/256.,"y":g.memory[0x58]as f32+g.memory[0x590]as f32/256.}));}out.push(serde_json::json!({"terrain":terrain,"input":input,"samples":samples}));}}println!("{}",serde_json::to_string(&out).unwrap());}